    if op == '+':
        result.append(operand[i] + operand[i+1])
    elif op == '-':
        result.append(operand[i] - operand[i+1])
    elif op == '*':
        result.append(operand[i] * operand[i+1])
    elif op == '/':
        result.append(operand[i] // operand[i+1])
    elif op == '**':
        result.append(operand[i] ** operand[i+1])
return result

